#define _CRT_SECURE_NO_WARNINGS
#include <stdio.h>

void SmallestEven(int values[], int length) {
    int smallestEven = -1; // Initialize to -1 to handle case where no even number is found.

    // Loop through the array to find the smallest even number.
    for (int i = 0; i < length; i++) {
        if (values[i] % 2 == 0) { // Check if the number is even.
            if (smallestEven == -1 || values[i] < smallestEven) {
                smallestEven = values[i]; // Update the smallest even number.
            }
        }
    }

    // Output the result.
    if (smallestEven != -1) {
        printf("The smallest even number is: %d\n", smallestEven);
    }
    else {
        printf("No even number found in the array.\n");
    }
}

#define _CRT_SECURE_NO_WARNINGS
#include <stdio.h>

void SmallestEven(int values[], int length) {
    int smallestEven = -1; // Initialize to -1 to handle case where no even number is found.

    // Loop through the array to find the smallest even number.
    for (int i = 0; i < length; i++) {
        if (values[i] % 2 == 0) { // Check if the number is even.
            if (smallestEven == -1 || values[i] < smallestEven) {
                smallestEven = values[i]; // Update the smallest even number.
            }
        }
    }

    // Output the result.
    if (smallestEven != -1) {
        printf("The smallest even number is: %d\n", smallestEven);
    } else {
        printf("No even number found in the array.\n");
    }
}

int main() {
    int values[] = {50, 25, 2, 38, 45}; // Example array
    int n = 5; // Length of the array

    SmallestEven(values, n); // Call the function
    return 0;
}

