void SmallestEven(int values[], int length) {
    if (length == 0) {
        printf("Array is empty.\n");
        return;
    }

    int smallestEven = 0; // Initialize with a default value
    int foundEven = 0; // Flag to check if an even number is found
    int index = -1; // To store the index of the smallest even number

    for (int i = 0; i < length; i++) {
        if (values[i] % 2 == 0) { // Check if the current number is even
            if (!foundEven || values[i] < smallestEven) {
                smallestEven = values[i];
                index = i; // Update index of the smallest even number
                foundEven = 1; // Set the flag since we've found an even number
            }
        }
    }

    if (foundEven) {
        printf("The smallest even number is %d at index %d.\n", smallestEven, index);
    } else {
        printf("No evens.\n");
    }
}

