#include <stdio.h>

int SmallestEven(int values[], int length) {
    int smallestEven = -1;

    for (int i = 0; i < length; i++) {
        if (values[i] % 2 == 0 && (smallestEven == -1 || values[i] < smallestEven)) {
            smallestEven = values[i];
        }
    }

    return smallestEven;
}

int main() {
    int values[] = {50, 25, 2, 30, 45};
    int n = 5;
    int result = SmallestEven(values, n);

    if (result != -1) {
        printf("Smallest even value: %d\n", result);
    } else {
        printf("No even values found.\n");
    }

    return 0;
}

