#include <stdio.h>
#include <limits.h>

void SmallestEven(int values[], int length) {
    if (length == 0) {
        printf("Error: The array is empty.\n");
        return;
    }

    int smallestEven = INT_MAX;
    int foundEven = 0;
    for (int i = 0; i < length; i++) {
        if (values[i] % 2 == 0) {
            if (values[i] < smallestEven) {
                smallestEven = values[i];
                foundEven = 1;
            }
        }
    }

    if (foundEven) {
        printf("The smallest even number is: %d\n", smallestEven);
    } else {
        printf("Error: No even numbers found in the array.\n");
    }
}

int main() {
    int values[] = {5, 3, 7, 8, 2};
    int length = sizeof(values) / sizeof(values[0]);

    SmallestEven(values, length);

    return 0;
}

