#include <stdio.h>
#include <limits.h> // For INT_MAX

void SmallestEven(int values[], int length) {
    int smallestEven = INT_MAX; // Initialize to maximum integer value
    int foundEven = 0; // Flag to track if any even number is found

    for (int i = 0; i < length; i++) {
        if (values[i] % 2 == 0) { // Check if the number is even
            if (values[i] < smallestEven) {
                smallestEven = values[i]; // Update smallest even number
            }
            foundEven = 1; // Mark that we've found at least one even number
        }
    }

    if (foundEven) {
        printf("The smallest even value is: %d\n", smallestEven);
    } else {
        printf("There are no even values in the array.\n");
    }
}

int main() {
    int values[] = {50, 25, 2, 30, 45}; // Sample input array
    int n = sizeof(values) / sizeof(values[0]); // Calculate the size of the array

    SmallestEven(values, n); // Call the function
    return 0;
}

