#include <stdio.h>

void SmallestEven(int values[], int length) {
    int smallestEven = -1;  // Placeholder for no even values found
    for (int i = 0; i < length; i++) {
        if (values[i] % 2 == 0) {  // Check if the value is even
            if (smallestEven == -1 || values[i] < smallestEven) {
                smallestEven = values[i];
            }
        }
    }

    if (smallestEven == -1) {
        printf("No even values found.\n");
    } else {
        printf("Smallest even value: %d\n", smallestEven);
    }
}

