#include <stdio.h>

void SmallestEven(int values[], int length) {
    int smallestEven = -1; 


    for (int i = 0; i < length; i++) {
        if (values[i] % 2 == 0) { 
            if (smallestEven == -1 || values[i] < smallestEven) {
                smallestEven = values[i];  
            }
        }
    }


    if (smallestEven == -1) {
        printf("No even numbers found.\n");
    } else {
        printf("The smallest even number is: %d\n", smallestEven);
    }
}

