#include <stdio.h>

int CheckForEven(int values[], int length) {
    for (int i = 0; i < length; i++) {
        if (values[i] % 2 == 0) {  // Check if the number is even
            return values[i];  // Return the first even number
        }
    }
    return -1;  // Return -1 if no even numbers are found
}

#include <stdio.h>

int CheckForEven(int values[], int length) {
    for (int i = 0; i < length; i++) {
        if (values[i] % 2 == 0) {  // Check if the number is even
            return values[i];  // Return the first even number
        }
    }
    return -1;  // Return -1 if no even numbers are found
}

int main() {
    int values1[] = {1, 3, 5, 7};  // No even numbers

    // Test case
    printf("First even number: %d\n", CheckForEven(values1, 4));  // Expected: -1

    return 0;
}

