#include <stdio.h>
#include <limits.h>  // For INT_MAX

// Function to find the smallest even value
int SmallestEven(int values[], int length) {
    if (length == 0) return -1;  // Handle empty array case

    int smallestEven = INT_MAX;  // Initialize to max possible value

    for (int i = 0; i < length; i++) {
        if (values[i] % 2 == 0) {  // Check if number is even
            if (values[i] < smallestEven) {
                smallestEven = values[i];  // Update smallest even number
            }
        }
    }

    return (smallestEven == INT_MAX) ? -1 : smallestEven;  // If no even found, return -1
}

// Main function
int main() {
    int values1[] = {1, 3, 5, 7};  // No even numbers
    int values2[] = {4, 8, 12, 2, 6, 2};  // Smallest even is 2
    int values3[] = {-10, -4, -2, 5};  // Smallest even is -10
    int values4[] = {2};  // Only one element, which is even

    // Test cases
    printf("Smallest even (values1): %d\n", SmallestEven(values1, 4));  // Expected: -1
    printf("Smallest even (values2): %d\n", SmallestEven(values2, 6));  // Expected: 2
    printf("Smallest even (values3): %d\n", SmallestEven(values3, 4));  // Expected: -10
    printf("Smallest even (values4): %d\n", SmallestEven(values4, 1));  // Expected: 2

    return 0;
}

#include <stdio.h>
#include <limits.h>  // For INT_MAX

// Function to find the smallest even value
int SmallestEven(int values[], int length) {
    int smallestEven = INT_MAX;  // Start with the largest possible value

    for (int i = 0; i < length; i++) {
        if (values[i] % 2 == 0) {  // Check if the number is even
            if (values[i] < smallestEven) {
                smallestEven = values[i];  // Update smallest even number
            }
        }
    }

    // Return -1 if no even number was found
    if (smallestEven == INT_MAX) {
        return -1;
    }

    return smallestEven;
}

int main() {
    // Test 1: Check behavior with no even numbers
    int values1[] = {1, 3, 5, 7};  // No even numbers
    printf("Test 1 (no evens): %d\n", SmallestEven(values1, 4));  // Expected: -1

    // Test 2: All numbers are even
    int values2[] = {50, 25, 2, 30, 45};  // Smallest even is 2
    printf("Test 2 (mixed evens): %d\n", SmallestEven(values2, 5));  // Expected: 2

    // Test 3: Includes negative even numbers
    int values3[] = {-10, -4, -2, 5};  // Smallest even is -10
    printf("Test 3 (negative evens): %d\n", SmallestEven(values3, 4));  // Expected: -10

    // Test 4: All numbers are even
    int values4[] = {10, 4, 12, 2, 8};  // Smallest even is 2
    printf("Test 4 (all evens): %d\n", SmallestEven(values4, 5));  // Expected: 2

    return 0;
}

