void SmallestEven(int values[], int length)
{
    int i, pos;
    int temp = values[0];
    int foundeven = 0;

    for (i = 0; i < length; i++) {
            // Check if the current value is even
            if (values[i] % 2 == 0) {
                if (!foundeven) {
                    // First even number found, set it as the smallest even
                    temp = values[i];
                    pos = i;
                    foundeven = 1;  // Mark that an even number has been found
                } else if (values[i] < temp) {
                    // Update the smallestEven if the current even number is smaller
                    temp = values[i];
                    pos = i;
                }
            }
        }

        // If no even number was found, return -1
        if (!foundeven) {
            printf("No evens");
        }
        else{
            printf("%d ", pos);
        }


}

