int LargestValue(int values[], int length) {
    // 初始化 max 为数组的第一个元素
    int max = values[0];

    // 从数组的第二个元素开始遍历，直到数组的最后一个元素
    for (int i = 1; i < length; i++) {
        if (values[i] > max) {
            max = values[i]; // 更新最大值
        }
    }

    // 返回找到的最大值
    return max;
}

#include <stdio.h>
#include <limits.h>  // 用于 INT_MAX

void SmallestEven(int values[], int length) {
    int smallest_even = INT_MAX;  // 初始化为最大整数，方便比较
    int found = 0;  // 标记是否找到了偶数

    for (int i = 0; i < length; i++) {
        if (values[i] % 2 == 0) {  // 判断是否是偶数
            if (values[i] < smallest_even) {
                smallest_even = values[i];  // 更新最小偶数
                found = 1;  // 标记找到偶数
            }
        }
    }

    if (found) {
        printf("The smallest even value is: %d\n", smallest_even);
    } else {
        printf("No even value found.\n");
    }
}

