#include <stdio.h>

void PrintArray(int values[], int length) {
    for (int i = 0; i < length; i++) {
        printf("%d ", values[i]);
    }
    printf("\n");
}

int main() {
    int values[] = {1, 2, 3, 4, 5};  // 声明并初始化数组
    int n = 5;  // 声明并初始化数组长度

    PrintArray(values, n);  // 调用函数，传递数组和长度

    return 0;
}

