#include <stdio.h>
#include <limits.h>  // For INT_MAX

int SmallestEven(int values[], int length) {
    int minEven = INT_MAX;  // Initialize to the largest possible integer
    int foundEven = 0;  // Flag to check if an even number is found

    // Loop through the array to find the smallest even value
    for (int i = 0; i < length; i++) {
        if (values[i] % 2 == 0) {  // Check if the number is even
            if (values[i] < minEven) {
                minEven = values[i];
                foundEven = 1;  // Set the flag to true when an even number is found
            }
        }
    }

    // If no even number was found, return -1
    if (!foundEven) {
        return -1;
    }

    // Return the smallest even value
    return minEven;
}

