#include <stdio.h>
#include <limits.h>

int SmallestEven(int values[], int length) {
    int mineven = INT_MAX;
    for (int i = 0; i < length; i++) {
        if (values[i] % 2 == 0) {
            if (values[i] < mineven) {
                mineven = values[i];
            }
        }
    }

    if (mineven == INT_MAX) {
        return -1;
    }

    return mineven;
}

