int SmallestEven(int values[], int length) {
    int smallestEven = -1;  // Start with a value indicating no even number found

    for (int i = 0; i < length; i++) {
        if (values[i] % 2 == 0) {  // Check if the number is even
            if (smallestEven == -1 || values[i] < smallestEven) {
                smallestEven = values[i];  // Update the smallest even number
            }
        }
    }

    return smallestEven;
}

