void SmallestEven(int values[], int length) 
{
    int smallest = 1000000;
    int positions[length];
    int Count = 0;

    for (int i = 0; i < length; i++) {
        if (values[i] % 2 == 0) { 
            if (values[i] < smallest) {

                smallest = values[i];
                Count = 0;
                positions[Count++] = i;
            } else if (values[i] == smallest) {

                positions[Count++] = i;
            }
        }
    }
    if (Count == 0) {
        printf("No evens\n");
    } else {
        for (int i = Count - 1; i >= 0; i--) {
            printf("%d ", positions[i]);
        }
        printf("\n");
    }
}

