// Function to find the smallest even number in an array
void SmallestEven(int values[], int length) {
    int smallestEven = INT_MAX;  // Initialize to maximum possible int value
    int foundEven = 0;           // Flag to check if even number is found

    for (int i = 0; i < length; i++) {
        if (values[i] % 2 == 0) {  // Check if the number is even
            foundEven = 1;
            if (values[i] < smallestEven) {
                smallestEven = values[i];
            }
        }
    }

    if (foundEven) {
        printf("The smallest even number is: %d\n", smallestEven);
    } else {
        printf("No even numbers found in the array.\n");
    }
}

