void SmallestEven(int values[], int length) 
{
    int sval = 0;  
    int even = -1;      

    for (int index = 0; index < length; index++) 
    {
        if (values[index] % 2 == 0) 
        { 
            if (even==-1) 
            {  
                sval = values[index];  
                even = 1;  
            } 
            else if (values[index] < sval) 
            {  
                sval = values[index];  
            }
        }
    }
}

