#include <stdio.h>

// Function prototype
void PrintArray(int values[], int length);

int main() {
    // Declare and initialize the array and its length
    int values[] = {50, 25, 2, 30, 45}; // Example values
    int n = sizeof(values) / sizeof(values[0]); // Calculate length

    // Call the function with the correct parameters
    PrintArray(values, n);

    return 0;
}

// Example implementation of PrintArray
void PrintArray(int values[], int length) {
    for (int i = 0; i < length; i++) {
        printf("%d ", values[i]);
    }
    printf("\n");
}

