#include <stdio.h>
#include <limits.h>  // For INT_MAX

int SmallestEvenValue(int values[], int length) {
    int minEven = INT_MAX;  // Initialize to the largest possible integer

    for (int a = 0; a < length; a++) {
        // Check if the current value is even
        if (values[a] % 2 == 0) {
            // Update the minEven if the current value is smaller
            if (values[a] < minEven) {
                minEven = values[a];
            }
        }
    }

    // If no even value was found, return -1 as an indicator
    if (minEven == INT_MAX) {
        return -1;
    }

    return minEven;
}

// If PrintArray function exists in the code, you must define it
void PrintArray(int values[], int length) {
    for (int a = 0; a < length; a++) {
        printf("%d ", values[a]);
    }
    printf("\n");
}

int main() {
    int values[] = {50, 25, 2, 30, 45};
    int n = sizeof(values) / sizeof(values[0]);

    int result = SmallestEvenValue(values, n);

    if (result == -1) {
        printf("No even values found.\n");
    } else {
        printf("Smallest even value: %d\n", result);
    }

    PrintArray(values, n);  // This assumes PrintArray function exists

    return 0;
}

