    int minEven = INT_MAX;

    for (int a = 0; a < length; a++) {
        if (values[a] % 2 == 0) {
            if (values[a] < minEven) {
                minEven = values[a];
            }
        }
    }

    if (minEven == INT_MAX) {
        printf("-1\n");
