#include <stdio.h>
#include <limits.h> 

void SmallestEven(int values[], int length) {
    int smallestEven = INT_MAX;
    int foundEven = 0;
    for (int i = 0; i < length; i++) {
        if (values[i] % 2 == 0) { 
            if (values[i] < smallestEven) {
                smallestEven = values[i];
                foundEven = 1;
            }
        }
    }

    if (!foundEven) {
        printf("-1\n");
    } else {
        printf("%d\n", smallestEven);
    }
}

int main() {
    int values[] = {50, 25, 2, 30, 45};
    int n = 5;
    SmallestEven(values, n);

    return 0;
}

