#include <limits.h>

void SmallestEven(int values[], int length) {
    int smallestEven = INT_MAX;

    for (int i = 0; i < length; i++) {
        if (values[i] % 2 == 0 && values[i] < smallestEven) {
            smallestEven = values[i];
        }
    }

    if (smallestEven == INT_MAX) {
        printf("No even number found\n");
    } else {
        printf("Smallest even number: %d\n", smallestEven);
    }
}

