#include <stdio.h>

void SmallestEven(int values[], int length) {
    int low = -1;
    int n_low[length];
    int size = 1;
    int start = 0;

    for (int i = length - 1; i >= 0; i--) {
        if (values[i] % 2 == 0) {
            if (start == 0 || values[i] < low) {
                low = values[i];
                n_low[0] = i;
                start = 1;
                size = 1;
            } else if (values[i] == low) {
                n_low[size] = i;
                size++;
            }
        }
    }

    if (start == 0) {
        printf("No evens");
        return;
    }

    for (int j = 0; j < size; j++) {
        printf("%d ", n_low[j]);
    }
}

