#include <limits.h>  // For INT_MAX

void SmallestEven(int values[], int length) {
    int smallest_even = INT_MAX;  // Initialize to a very large number
    int found_even = 0;  // Flag to track if any even number is found

    for (int i = 0; i < length; i++) {
        if (values[i] % 2 == 0) {  // Check if the number is even
            if (values[i] < smallest_even) {
                smallest_even = values[i];
                found_even = 1;
            }
        }
    }

    if (found_even) {
        printf("The smallest even value is: %d\n", smallest_even);
    } else {
        printf("No even values found.\n");
    }
}// You can modify any of these inputs as often as you like:
