// You can modify any of these inputs as often as you like:
void SmallestEven(int values[], int length)
{
    int min = -1, minIndex=-1;
    for (int i = 0; i < length; i++) {
        if (values[i] % 2 == 0) {  // Check if the number is even
            if (min == -1 || values[i] < min) {
                min = values[i];
                minIndex = i;
            }
        }
    }
    if (minIndex == -1){
        printf("No evens\n");
        return;
    }
    for (int i = length-1; i >= 0; i--) {
        if (values[i] == min) {
            printf("%d ", i);
        }
    }
}

