#include <stdio.h>
#include <limits.h>

void SmallestEven(int values[], int length) {
    int smallestEven = INT_MAX;  // Initialize to maximum possible integer value
    int found = 0;  // Flag to check if any even number is found

    for (int i = 0; i < length; i++) {
        if (values[i] % 2 == 0) {  // Check if the number is even
            if (values[i] < smallestEven) {
                smallestEven = values[i];  // Update smallest even number
                found = 1;  // Set found flag to indicate an even number exists
            }
        }
    }

    // Print result based on whether an even number was found or not
    if (found) {
        printf("Smallest even number: %d\n", smallestEven);
    } else {
        printf("No even number found\n");
    }
}

#include <stdio.h>
#include <limits.h>

void SmallestEven(int values[], int length) {
    int smallestEven = INT_MAX;  // Initialize to maximum possible integer value
    int found = 0;  // Flag to check if any even number is found

    for (int i = 0; i < length; i++) {
        if (values[i] % 2 == 0) {  // Check if the number is even
            if (values[i] < smallestEven) {
                smallestEven = values[i];  // Update smallest even number
                found = 1;  // Set found flag to indicate an even number exists
            }
        }
    }

    // Print result based on whether an even number was found or not
    if (found) {
        printf("Smallest even number: %d\n", smallestEven);
    } else {
        printf("No even number found\n");
    }
}

