// You can modify any of these inputs as often as you like:
int values[] = {50, 25, 2, 30, 45};
int n = 5;

#include <stdio.h>  
#include <limits.h>  

void SmallestEven(int values[], int length) {  
    int min = INT_MAX; 
    int found = 0; 
    for (int i = 0; i < length; i++) {  
        if (values[i] % 2 == 0) { 
            if (values[i] < min) { 
                min = values[i];  
                found = 1; 
            }  
        }  
    }  


    if (found) {  
        printf("The smallest even number is: %d\n", min);  
    } else {  
        printf("No even numbers found.\n");  
    }  
}  

int main() {  
    int values[] = {50, 25, 2, 30, 45};  
    int n = sizeof(values) / sizeof(values[0]); // Calculate the length of the array  

    SmallestEven(values, n); // Call the function  
    return 0;  
}

