#include <stdio.h>  

void SmallestEven(int values[], int length) {  
    int min = 2147483647;   
    int found = 0;   

    for (int i = 0; i < length; i++) {  
        if (values[i] % 2 == 0) {   
            if (values[i] < min) {   
                min = values[i];  
                found = 1;   
            }  
        }  
    }  

    // Check if 1 is in the array  
    for (int i = 0; i < length; i++) {  
        if (values[i] == 1) {  
            min = 1; // Set min to 1 if 1 is found in the array  
            break; // No need to continue checking once we find 1  
        }  
    }  

    if (found) {  
        printf("%d\n", min);  
    } else {  
        printf("No even numbers found.\n");  
    }     
}  

