#include <stdio.h>  

void SmallestEven(int values[], int length) {  
    int min = 2147483647;   
    int found = 0;   
    int indices[10];  // Assuming the maximum number of even numbers is 10.  
    int count = 0;  

    for (int i = 0; i < length; i++) {  
        if (values[i] % 2 == 0) {   
            if (values[i] < min) {   
                min = values[i];  
                found = 1;  
                count = 0;  // Reset count for new minimum  
                indices[count++] = i; // Store index of the new minimum  
            } else if (values[i] == min) {  
                indices[count++] = i; // Store index of equal minimum  
            }  
        }  
    }  

    if (found) {  
        // Print indices starting with the last one found  
        for (int j = count - 1; j >= 0; j--) {  
            printf("%d", indices[j]);  
            if (j > 0) {  
                printf(" "); // Add space between indices  
            }  
        }  
        printf("\n");  
    } else {  
        printf("No even numbers found.\n");  
    }     
}  

